            background:
              "Azure Collection mengoperasikan 4 resor mewah di seluruh Maladewa: Azure North (Atol Malé Utara), Azure South (Atol Malé Selatan), Azure Private Island (Atol Baa), dan Azure Retreat (Atol Raa). Direktur kebugaran grup mereka, Simone Devereux, 39 tahun, mantan instruktur yoga profesional dari Australia, telah bersama Azure selama 7 tahun. Pada 2022, Simone mensurvei 2.800 tamu di 4 properti dan menemukan 73% tamu menyatakan minat pada kelas SUP yoga, tetapi hanya 12% yang benar-benar memesan — dengan hambatan utama 'kurang percaya diri di papan sempit' (disebut oleh 64% yang tidak memesan). Armada SUP yang ada (papan berusia 3 tahun dari OEM generik Tiongkok) totalnya 14 papan, cocok untuk pendayungan air tenang tetapi tidak stabil untuk yoga: papan selebar 32\" dengan dek EVA licin. Simone membutuhkan armada papan SUP yoga yang dibangun khusus dengan lebar ekstra, permukaan dek berbantalan anti-slip yang cocok untuk latihan yoga tanpa alas kaki, dan kemampuan menahan hingga 350 lbs untuk pose yoga berpasangan.",
            goal: 'Mengerahkan armada 40 papan SUP yoga khusus di 4 resor, mengembangkan program SUP yoga berjenjang (Pemula, Menengah, Lanjutan, Berpasangan) dengan instruktur terlatih, dan meningkatkan konversi pemesanan SUP yoga dari 12% menjadi 35% dalam 12 bulan.',
