            goal: 'Melengkapi 4 kapal Hurtigruten (MS Fram, MS Midnatsol, MS Trollfjord, dan MS Maud) dengan 60 paket SUP portabel kelas kutub yang diterjunkan dari Zodiac dalam kondisi Arktik, menahan rentang suhu -15°C hingga +10°C, protokol pertemuan beruang kutub, dan mempertahankan standar pengalaman tamu mewah.',
